$tahap = intval($params["tahap"]);
$result = array();
$jumlah = 0;

while($record = $button->getNextSelectedRecord())
{
    $sql = DB::PrepareSQL(
        "UPDATE data_sibay
         SET kunci_kemenag_pidie = 'selesai'
         WHERE npsn = ':1' AND tahap = ':2' AND tahun = ':3'",
        trim($record["npsn"]), $tahap, trim($record["tahun"])
    );
    DB::Exec($sql);
    $jumlah++;
}

$result["jumlah"] = $jumlah;

